contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Record tokenBalance of caller before airDrop
        uint256 prevBalanceCaller = c.tokenBalance(caller);
        // Also record tokenBalance of some other address; we'll check that no balance ever decreases
        address other = address(0xdead);
        uint256 prevBalanceOther = c.tokenBalance(other);

        vm.prank(caller);
        // The call might revert due to modifiers; we need to check only when it succeeds
        bool ok = true;
        try c.airDrop() { ok = true; } catch { ok = false; }

        // If the call succeeded, then no tokenBalance may have decreased.
        // If it failed (reverted), the state should be unchanged, so the property holds trivially.
        // The property is: After airDrop(), for every address, tokenBalance >= previous tokenBalance.
        // We check it for two addresses (caller and another).
        // The mutant can overflow and wrap around, decreasing the caller's balance, making it < prevBalanceCaller.
        assertTrue(!ok || (c.tokenBalance(caller) >= prevBalanceCaller && c.tokenBalance(other) >= prevBalanceOther));
    }
}

