contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address observer) public {
        // observer represents the key 'k' whose balance we inspect
        vm.assume(caller != address(0));
        vm.assume(observer != address(0));
        vm.assume(caller != observer);
        // record pre-balance of observer
        uint256 pre = c.tokenBalance(observer);
        // attempt airDrop as caller via a Bank-like helper that satisfies supportsToken
        // we deploy a minimal helper that returns the expected bytes32
        Helper helper = new Helper();
        vm.prank(caller);
        try c.airDrop(helper) {
            // success branch: compute post-balance of observer
            uint256 post = c.tokenBalance(observer);
            // rule: after a successful airdrop, the observer's balance must be:
            // if observer == caller -> >= 20
            // if observer != caller -> unchanged (pre == post)
            assertTrue(
                (observer == caller && post >= 20) ||
                (observer != caller && post == pre)
            );
        } catch {
            // revert branch: rule vacuously holds (no state change to check)
            assertTrue(true);
        }
    }
}

