pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint8 callCount) public {
        // Restrict callCount to a reasonable range to keep fuzzing fast (1 to 10)
        callCount = uint8(bound(callCount, 1, 10));

        // Record initial total balance
        uint256 totalBefore = 0;

        // Make `callCount` airDrop calls from the same caller
        for (uint256 i = 0; i < callCount; i++) {
            // Setup: ensure caller has zero balance before each attempt
            // but after first call the hasNoBalance modifier will revert.
            // Pre-fund caller with a new address for each iteration to satisfy hasNoBalance.
            address freshCaller = address(uint160(uint256(keccak256(abi.encode(caller, i)))));

            // The airdrop requires the caller to be a Bank returning the correct token.
            // We deploy a minimal Bank helper for this caller.
            Bank bank = new Bank();
            address bankAddr = address(bank);

            // To make `supportsToken` modifier pass, we need `Bank(msg.sender).supportsToken()` to return correct hash.
            // The caller address in the modifier is `msg.sender` (inside airdrop).
            // So we deploy Bank at a deterministic address, but `msg.sender` must be the Bank's address.
            // The modifier checks `Bank(msg.sender).supportsToken()`.
            // So we need `msg.sender` to be a Bank contract. We deploy a Bank, then prank from its address.
            vm.prank(bankAddr);
            try c.airDrop() { 
                totalBefore += 20;
            } catch { }
        }

        // Compute actual total balance by summing all token balances.
        // Since addresses are deterministic from the loop, we can reconstruct them.
        uint256 actualTotal = 0;
        for (uint256 i = 0; i < callCount; i++) {
            address freshCaller = address(uint160(uint256(keccak256(abi.encode(caller, i)))));
            actualTotal += c.tokenBalance(freshCaller);
        }

        // Invariant: total tokens minted = 20 * successful calls
        assertTrue(actualTotal == totalBefore);
    }
}

