import {Test} from "forge-std/StdTest.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // 1. Restrict admissible domain: Exclude precompile addresses and the test contract itself, and ensure caller is not address(0).
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        vm.assume(caller.code.length == 0);

        // 2. Set up the scenario: caller is an EOA. We need them to be a Bank that returns the correct token.
        //    Since caller is an EOA, any call to caller.supportsToken() will succeed (returning empty bytes).
        //    The supportsToken modifier requires keccak256("Nu Token") == Bank(caller).supportsToken().
        //    An EOA always returns true for a low-level call, but the return data from a low-level call to an EOA is empty, so keccak256("") != keccak256("Nu Token").
        //    Thus, calling airDrop from a plain EOA will revert on the supportsToken modifier. To test the airdrop logic, we need a contract that acts as a Bank.
        //    Deploy an adversarial helper that is both the caller and implements supportsToken correctly.
        BankActor bank = new BankActor();
        //    bank's address will act as our caller.
        address actor = address(bank);

        //    bank has no balance initially (hasNoBalance passes).
        //    Perform a first airdrop; it must succeed.
        bool firstOk = bank.attemptAirdrop(c);
        assertTrue(firstOk); // required to proceed; we assume the first call succeeds for a fresh actor.

        //    After the first airdrop, the reference C enforces that no second airdrop can succeed without a prior balance change (transfer out) because hasNoBalance requires balance == 0.
        //    The buggy version (without hasNoBalance) allows a second airdrop to succeed even with a non-zero balance.
        //    We check whether a second airdrop attempt succeeds. The rule: after one successful airdrop, the next attempt must fail.
        bool secondOk = bank.attemptAirdrop(c);
        assertTrue(!secondOk); // The reference ensures the second call reverts; the bug allows it, violating this.
    }
}

