import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[3] memory callers) public {
        // Ensure all callers are distinct and not the zero address
        vm.assume(callers[0] != address(0) && callers[1] != address(0) && callers[2] != address(0));
        vm.assume(callers[0] != callers[1]);
        vm.assume(callers[0] != callers[2]);
        vm.assume(callers[1] != callers[2]);

        uint256 distinctCount = 0;
        for (uint256 i = 0; i < callers.length; i++) {
            // Each caller attempts airdrop. We track success by checking if balance changes from 0 to 20.
            // The bug allows repeated claims, so the same caller might succeed multiple times.
            // We simulate by having each caller claim airdrop multiple times in separate blocks
            // to test the invariant over arbitrary sequences.
            uint256 beforeBalance = c.tokenBalance(callers[i]);
            vm.prank(callers[i]);
            try c.airDrop() {
                // success
            } catch {
                // fail
            }
            uint256 afterBalance = c.tokenBalance(callers[i]);
            if (afterBalance > beforeBalance) {
                distinctCount++;
            }
        }

        // Calculate total supply across all tracked callers
        uint256 totalSupply = c.tokenBalance(callers[0]) + c.tokenBalance(callers[1]) + c.tokenBalance(callers[2]);

        // Invariant: total supply must equal 20 * distinctCount
        assertTrue(totalSupply == 20 * distinctCount);
    }
}

