pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address actor, address bankAddr, uint8 choice) public {
        vm.assume(actor != address(0));
        vm.assume(bankAddr != address(0));
        // Simulate external party behavior: choice 0 = reverting callee, choice 1 = returning wrong token, choice 2 = returning correct token
        Helper helper;
        if (choice % 3 == 0) {
            helper = new Reverter();
        } else if (choice % 3 == 1) {
            helper = new WrongToken();
        } else {
            helper = new GoodBank();
        }

        vm.prank(actor);
        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After a call to airDrop, the balance can only be non-zero if the caller was a Bank that supports "Nu Token" exactly.
        // If it reverted, balance stays 0 (precondition hasNoBalance). If it succeeded, supportsToken must have passed.
        // Since supportsToken checks via keccak256(abi.encodePacked("Nu Token")) == Bank(msg.sender).supportsToken(),
        // only a Bank returning exactly that hash can succeed. The bug removes the require, so a revert-free call from any msg.sender
        // will cause tokenBalance[actor] to become 20, violating the invariant.
        if (!reverted) {
            assertTrue(
                keccak256(abi.encodePacked("Nu Token")) == helper.supportsToken()
            );
        }
    }
}

